ventas = [
    {"anio": 2024, "region": "norte", "monto": 100},
    {"anio": 2023, "region": "norte", "monto": 999},
    {"anio": 2024, "region": "sur", "monto": 250},
    {"anio": 2024, "region": "norte", "monto": 50},
]

def match(docs, campo, valor):
    return [d for d in docs if d[campo] == valor]

def group_sum(docs, campo_grupo, campo_suma):
    totales = {}
    for d in docs:
        clave = d[campo_grupo]
        totales[clave] = totales.get(clave, 0) + d[campo_suma]
    return [{"_id": k, "total": v} for k, v in totales.items()]

def sort_desc(docs, campo):
    return sorted(docs, key=lambda d: d[campo], reverse=True)

etapa1 = match(ventas, "anio", 2024)
etapa2 = group_sum(etapa1, "region", "monto")
etapa3 = sort_desc(etapa2, "total")

print("resultado del pipeline:", etapa3)
